const Home = () => {
  const API_URL = "https://fakestoreapi.com/products";
  const [loading,setLoading]= useState();
  return(
    async function fetchProductData(){
      setLoading(true);
      try{
        const res = await fetch(API_URL);
        const data = res.json();
        setPost(data);

      }
      catch(error){
        console.log("error aaya hai");
      }
      
      setLoading(false);
    }
  )
};

export default Home;
